"""Build a packaged Pantheon MCP adapter runtime into a ROOT (T-2915, T-2916).

Two adapter profiles share ONE hash-locked runtime (ORG-052 §7 "one
pinned runtime"; ``requirements.lock`` in this directory is the single
source):

- ``host`` (default; T-2915): the seven-tool HostBroker1 adapter;
- ``approval`` (T-2916): the four-tool HostApproval1.Reviewer adapter.

Each profile builds its own separate tree from that one lock, under
``--root`` (a fixture root in tests; the real install is the T-2920
install leg, run by the head orchestrator). For the host profile:

    usr/local/lib/pantheon/host-mcp-adapter/venv/        pinned runtime
    usr/local/lib/pantheon/host-mcp-adapter/app/tools/   adapter modules
    usr/local/lib/pantheon/host-mcp-adapter/BUILD-MANIFEST.json
    usr/local/libexec/pantheon-host-mcp-adapter          launcher

and the same shape under ``approval-mcp-adapter`` /
``pantheon-approval-mcp-adapter`` for the approval profile. The host
profile's inputs stay frozen to the T-2915 bytes (pinned by
``tools/test_approval_mcp_adapter.py``), so its output is unchanged.

Every wheel comes from a local ``--wheelhouse`` and must match
``requirements.lock`` by sha256 (``--require-hashes --no-deps
--only-binary=:all: --no-index``); a mismatch aborts the build. Nothing
is installed outside ``--root``. The launcher runs the venv interpreter
with ``-I`` (no user site, no PYTHON* environment, no script dir on
sys.path) and puts only the packaged app dir on ``sys.path``.

Console scripts that wheels drop into ``venv/bin`` are removed: the
adapter never runs them, and they would carry build-root shebangs.

Paths are PROVISIONAL (ORG-052 §7 names only the libexec launcher);
T-2920 owns the final install layout.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

DIST_DIR = Path(__file__).resolve().parent
PACKAGE_DIR = DIST_DIR.parent
REQUIREMENTS_IN = DIST_DIR / "requirements.in"
REQUIREMENTS_LOCK = DIST_DIR / "requirements.lock"

PREFIX = Path("usr/local/lib/pantheon/host-mcp-adapter")
LAUNCHER = Path("usr/local/libexec/pantheon-host-mcp-adapter")
MANIFEST_NAME = "BUILD-MANIFEST.json"
MANIFEST_SCHEMA = "pantheon-host-mcp-adapter-build/v1"

# The ONLY modules that ship. Test drivers (which may point the client
# at a private bus) are never packaged (ORG-052 §7 test-mode rule).
PACKAGED_MODULES = ("__init__.py", "contract.py", "bus_client.py", "server.py")

LAUNCHER_TEXT = """#!/{venv_python} -I
# pantheon-host-mcp-adapter - GENERATED by build_runtime.py (T-2915).
import sys
from pathlib import Path

# The runtime is immutable after build: never write bytecode at run time.
sys.dont_write_bytecode = True
_APP =Path(__file__).resolve().parent.parent / "lib" / "pantheon" / "host-mcp-adapter" / "app"
sys.path.insert(0, str(_APP))

from tools.host_mcp_adapter.server import main

raise SystemExit(main())
"""


APPROVAL_PACKAGE_DIR = PACKAGE_DIR.parent / "approval_mcp_adapter"
APPROVAL_PREFIX = Path("usr/local/lib/pantheon/approval-mcp-adapter")
APPROVAL_LAUNCHER = Path("usr/local/libexec/pantheon-approval-mcp-adapter")
APPROVAL_MANIFEST_SCHEMA = "pantheon-approval-mcp-adapter-build/v1"
# The approver binary's closed module set. Its test driver (which may
# point the client at a private bus) is never packaged.
APPROVAL_PACKAGED_MODULES = ("__init__.py", "contract.py", "bus_client.py", "server.py")

APPROVAL_LAUNCHER_TEXT = """#!/{venv_python} -I
# pantheon-approval-mcp-adapter - GENERATED by build_runtime.py (T-2916).
import sys
from pathlib import Path

# The runtime is immutable after build: never write bytecode at run time.
sys.dont_write_bytecode = True
_APP = Path(__file__).resolve().parent.parent / "lib" / "pantheon" / "approval-mcp-adapter" / "app"
sys.path.insert(0, str(_APP))

from tools.approval_mcp_adapter.server import main

raise SystemExit(main())
"""


@dataclass(frozen=True)
class AdapterProfile:
    """Everything that differs between the packaged adapters. The lock,
    the hash-locked install discipline and verification are shared."""

    name: str
    package: str
    package_dir: Path
    prefix: Path
    launcher: Path
    manifest_schema: str
    packaged_modules: tuple[str, ...]
    launcher_text: str


HOST_PROFILE = AdapterProfile(
    name="host",
    package="host_mcp_adapter",
    package_dir=PACKAGE_DIR,
    prefix=PREFIX,
    launcher=LAUNCHER,
    manifest_schema=MANIFEST_SCHEMA,
    packaged_modules=PACKAGED_MODULES,
    launcher_text=LAUNCHER_TEXT,
)
APPROVAL_PROFILE = AdapterProfile(
    name="approval",
    package="approval_mcp_adapter",
    package_dir=APPROVAL_PACKAGE_DIR,
    prefix=APPROVAL_PREFIX,
    launcher=APPROVAL_LAUNCHER,
    manifest_schema=APPROVAL_MANIFEST_SCHEMA,
    packaged_modules=APPROVAL_PACKAGED_MODULES,
    launcher_text=APPROVAL_LAUNCHER_TEXT,
)
PROFILES = {profile.name: profile for profile in (HOST_PROFILE, APPROVAL_PROFILE)}


class BuildError(RuntimeError):
    pass


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 16), b""):
            digest.update(chunk)
    return digest.hexdigest()


def lock_is_current() -> bool:
    expected = hashlib.sha256(REQUIREMENTS_IN.read_bytes()).hexdigest()
    for line in REQUIREMENTS_LOCK.read_text(encoding="utf-8").splitlines():
        if line.startswith("# requirements.in sha256: "):
            return line.split(": ", 1)[1].strip() == expected
    return False


def manifest_entries(root: Path, profile: AdapterProfile = HOST_PROFILE) -> dict[str, str]:
    entries: dict[str, str] = {}
    for base in (root / profile.prefix, root / profile.launcher):
        paths = [base] if base.is_file() else sorted(base.rglob("*"))
        for path in paths:
            rel = path.relative_to(root).as_posix()
            if rel == (profile.prefix / MANIFEST_NAME).as_posix():
                continue
            if path.is_symlink():
                entries[rel] = "symlink:" + os.readlink(path)
            elif path.is_file():
                entries[rel] = "sha256:" + sha256_file(path)
    return entries


def _strip_group_other_write(root: Path, profile: AdapterProfile = HOST_PROFILE) -> None:
    for base in (root / profile.prefix, root / profile.launcher.parent):
        for path in [base, *base.rglob("*")]:
            if path.is_symlink():
                continue
            mode = path.stat().st_mode
            os.chmod(path, mode & ~0o022)


def build(
    root: Path,
    wheelhouse: Path,
    python: str = "/usr/bin/python3",
    profile: AdapterProfile = HOST_PROFILE,
) -> dict:
    root = root.resolve()
    if not lock_is_current():
        raise BuildError("requirements.lock is stale relative to requirements.in")
    prefix = root / profile.prefix
    if prefix.exists() or (root / profile.launcher).exists():
        raise BuildError("refusing to build over an existing artifact")
    venv = prefix / "venv"
    prefix.mkdir(parents=True)
    # -I on EVERY child interpreter (T-2920 U3a, Recovery D15 condition f): with -m and
    # no -I, sys.path[0] is the inherited cwd, so a planted venv/ or pip/ package
    # there would run as the (root) builder.
    subprocess.run([python, "-I", "-m", "venv", "--without-pip", str(venv)], check=True)
    venv_python = venv / "bin" / "python3"
    result = subprocess.run(
        [
            python,
            "-I",
            "-m",
            "pip",
            "--python",
            str(venv_python),
            "--disable-pip-version-check",
            "install",
            "--require-hashes",
            "--no-deps",
            "--only-binary=:all:",
            "--no-index",
            "--no-cache-dir",
            "--find-links",
            str(wheelhouse),
            "-r",
            str(REQUIREMENTS_LOCK),
            "-q",
        ],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise BuildError("hash-locked install failed: " + (result.stderr or result.stdout)[-2000:])
    for entry in (venv / "bin").iterdir():
        if not entry.name.startswith("python"):
            if entry.is_dir() and not entry.is_symlink():
                shutil.rmtree(entry)
            else:
                entry.unlink()

    app_package = prefix / "app" / "tools" / profile.package
    app_package.mkdir(parents=True)
    (prefix / "app" / "tools" / "__init__.py").write_text("", encoding="utf-8")
    for module in profile.packaged_modules:
        shutil.copyfile(profile.package_dir / module, app_package / module)
    subprocess.run(
        [str(venv_python), "-I", "-m", "compileall", "-q", str(prefix / "app")],
        check=True,
    )

    launcher = root / profile.launcher
    launcher.parent.mkdir(parents=True, exist_ok=True)
    production_venv_python = (profile.prefix / "venv" / "bin" / "python3").as_posix()
    launcher.write_text(profile.launcher_text.format(venv_python=production_venv_python), encoding="utf-8")
    os.chmod(launcher, 0o755)

    _strip_group_other_write(root, profile)
    manifest = {
        "schema": profile.manifest_schema,
        "requirements_lock_sha256": sha256_file(REQUIREMENTS_LOCK),
        "python": ".".join(str(part) for part in sys.version_info[:3]),
        "files": manifest_entries(root, profile),
    }
    manifest_path = prefix / MANIFEST_NAME
    manifest_path.write_text(json.dumps(manifest, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    os.chmod(manifest_path, 0o644)
    return manifest


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--root", required=True, type=Path)
    parser.add_argument("--wheelhouse", required=True, type=Path)
    parser.add_argument("--python", default="/usr/bin/python3")
    parser.add_argument("--adapter", choices=sorted(PROFILES), default=HOST_PROFILE.name)
    args = parser.parse_args(argv)
    try:
        manifest = build(args.root, args.wheelhouse, args.python, PROFILES[args.adapter])
    except BuildError as exc:
        print(f"build refused: {exc}", file=sys.stderr)
        return 1
    print(f"built {len(manifest['files'])} files under {args.root}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
